// ============================================================================
// chiplet_soc_ral_pkg -- UVM register model of the APB slots, generated by
// socgen from socgen/specs/chiplet_soc.yaml. Open-ip blocks come from docs/ip/<IP>.md of
// open-ip-portfolio @ 359f40a67051; the others from register_blocks.
//   chiplet_soc_reg_block   top block, map "map" at 0 (AXI byte addresses)
//   <slot>_blk          one sub-block per mapped APB slot
//   chiplet_soc_axi_reg_adapter  RAL <-> axi4_item, single 32-bit beats
// Registers whose value the hardware changes (core-backed, pop, W1C) are
// marked NO_REG_TESTS; the reset test checks the rest.
// ============================================================================
`ifndef CHIPLET_SOC_RAL_PKG_SV
`define CHIPLET_SOC_RAL_PKG_SV
package chiplet_soc_ral_pkg;
  import uvm_pkg::*;
  `include "uvm_macros.svh"
  import axi4_pkg::*;
  import chiplet_soc_pkg::*;

  // ======================= chiplet_soc_gpio_blk (open-ip docs/ip/GPIO.md) =======================
  class chiplet_soc_gpio_blk_id extends uvm_reg;
    `uvm_object_utils(chiplet_soc_gpio_blk_id)
    rand uvm_reg_field MINOR;
    rand uvm_reg_field MAJOR;
    rand uvm_reg_field CODE;
    function new(string name = "id");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      MINOR = uvm_reg_field::type_id::create("MINOR");
      MINOR.configure(this, 8, 0, "RO", 0, 8'h0, 1, 0, 0);
      MAJOR = uvm_reg_field::type_id::create("MAJOR");
      MAJOR.configure(this, 8, 8, "RO", 0, 8'h2, 1, 0, 0);
      CODE = uvm_reg_field::type_id::create("CODE");
      CODE.configure(this, 16, 16, "RO", 0, 16'h4750, 1, 0, 0);
    endfunction
  endclass

  class chiplet_soc_gpio_blk_irq_status extends uvm_reg;
    `uvm_object_utils(chiplet_soc_gpio_blk_irq_status)
    rand uvm_reg_field F0;
    function new(string name = "irq_status");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      F0 = uvm_reg_field::type_id::create("F0");
      F0.configure(this, 1, 0, "W1C", 1, 1'h0, 1, 0, 0);
    endfunction
  endclass

  class chiplet_soc_gpio_blk_irq_enable extends uvm_reg;
    `uvm_object_utils(chiplet_soc_gpio_blk_irq_enable)
    rand uvm_reg_field F0;
    function new(string name = "irq_enable");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      F0 = uvm_reg_field::type_id::create("F0");
      F0.configure(this, 1, 0, "RW", 0, 1'h0, 1, 1, 0);
    endfunction
  endclass

  class chiplet_soc_gpio_blk_flags extends uvm_reg;
    `uvm_object_utils(chiplet_soc_gpio_blk_flags)
    rand uvm_reg_field VAL;
    function new(string name = "flags");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      VAL = uvm_reg_field::type_id::create("VAL");
      VAL.configure(this, 32, 0, "RO", 1, 32'h0, 1, 0, 0);
    endfunction
  endclass

  class chiplet_soc_gpio_blk_scratch extends uvm_reg;
    `uvm_object_utils(chiplet_soc_gpio_blk_scratch)
    rand uvm_reg_field SCRATCH;
    function new(string name = "scratch");
