      SCRATCH.configure(this, 32, 0, "RW", 0, 32'h0, 1, 1, 0);
    endfunction
  endclass

  class chiplet_soc_gpio_blk_oe extends uvm_reg;
    `uvm_object_utils(chiplet_soc_gpio_blk_oe)
