  endclass

  class chiplet_soc_gpio_blk_out extends uvm_reg;
    `uvm_object_utils(chiplet_soc_gpio_blk_out)
    rand uvm_reg_field F0;
    function new(string name = "out");
      super.new(name, 32, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      F0 = uvm_reg_field::type_id::create("F0");
      F0.configure(this, 8, 0, "RW", 1, 8'h0, 1, 1, 0);
