  class chiplet_soc_gpio_blk extends uvm_reg_block;
    `uvm_object_utils(chiplet_soc_gpio_blk)
    rand chiplet_soc_gpio_blk_id ID;
    rand chiplet_soc_gpio_blk_irq_status IRQ_STATUS;
    rand chiplet_soc_gpio_blk_irq_enable IRQ_ENABLE;
    rand chiplet_soc_gpio_blk_flags FLAGS;
    rand chiplet_soc_gpio_blk_scratch SCRATCH;
    rand chiplet_soc_gpio_blk_oe OE;
    rand chiplet_soc_gpio_blk_out OUT;
    rand chiplet_soc_gpio_blk_in IN;
    function new(string name = "chiplet_soc_gpio_blk");
      super.new(name, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      default_map = create_map("map", 0, 4, UVM_LITTLE_ENDIAN, 1);
      ID = chiplet_soc_gpio_blk_id::type_id::create("ID");
      ID.configure(this);
      ID.build();
      default_map.add_reg(ID, 'h000, "RO");
      IRQ_STATUS = chiplet_soc_gpio_blk_irq_status::type_id::create("IRQ_STATUS");
      IRQ_STATUS.configure(this);
      IRQ_STATUS.build();
      default_map.add_reg(IRQ_STATUS, 'h004, "RW");
      IRQ_ENABLE = chiplet_soc_gpio_blk_irq_enable::type_id::create("IRQ_ENABLE");
      IRQ_ENABLE.configure(this);
      IRQ_ENABLE.build();
      default_map.add_reg(IRQ_ENABLE, 'h008, "RW");
      FLAGS = chiplet_soc_gpio_blk_flags::type_id::create("FLAGS");
      FLAGS.configure(this);
      FLAGS.build();
      default_map.add_reg(FLAGS, 'h00C, "RO");
      uvm_resource_db#(bit)::set({"REG::", FLAGS.get_full_name()}, "NO_REG_TESTS", 1, this);
      SCRATCH = chiplet_soc_gpio_blk_scratch::type_id::create("SCRATCH");
      SCRATCH.configure(this);
      SCRATCH.build();
      default_map.add_reg(SCRATCH, 'h010, "RW");
      OE = chiplet_soc_gpio_blk_oe::type_id::create("OE");
      OE.configure(this);
      OE.build();
      default_map.add_reg(OE, 'h014, "RW");
      OUT = chiplet_soc_gpio_blk_out::type_id::create("OUT");
      OUT.configure(this);
      OUT.build();
      default_map.add_reg(OUT, 'h018, "RW");
      uvm_resource_db#(bit)::set({"REG::", OUT.get_full_name()}, "NO_REG_TESTS", 1, this);
      IN = chiplet_soc_gpio_blk_in::type_id::create("IN");
      IN.configure(this);
      IN.build();
      default_map.add_reg(IN, 'h01C, "RO");
      uvm_resource_db#(bit)::set({"REG::", IN.get_full_name()}, "NO_REG_TESTS", 1, this);
      lock_model();
    endfunction
  endclass

  // ======================= top block =======================
  class chiplet_soc_reg_block extends uvm_reg_block;
    `uvm_object_utils(chiplet_soc_reg_block)
    rand chiplet_soc_gpio_blk gpio;
    uvm_reg_map map;
    function new(string name = "chiplet_soc_reg_block");
      super.new(name, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      map = create_map("map", 0, 4, UVM_LITTLE_ENDIAN, 1);
      default_map = map;
      gpio = chiplet_soc_gpio_blk::type_id::create("gpio");
      gpio.configure(this);
      gpio.build();
      map.add_submap(gpio.default_map, 'h10000000);
      lock_model();
    endfunction
  endclass

  // RAL <-> AXI4: each register access is one INCR burst of one 32-bit beat
  class chiplet_soc_axi_reg_adapter extends uvm_reg_adapter;
    `uvm_object_utils(chiplet_soc_axi_reg_adapter)
    function new(string name = "chiplet_soc_axi_reg_adapter");
      super.new(name);
      supports_byte_enable = 1;
      provides_responses   = 0;      // the AXI driver writes the response into the request
    endfunction
    virtual function uvm_sequence_item reg2bus(const ref uvm_reg_bus_op rw);
      axi4_item t = axi4_item::type_id::create("ral_axi");
      t.write = (rw.kind == UVM_WRITE);
      t.id = 0; t.addr = 32'(rw.addr); t.len = 0; t.size = 3'd2; t.burst = AXI4_INCR;
      t.alloc();
      t.data[0] = 32'(rw.data);
      t.strb[0] = t.write ? 4'(rw.byte_en) : 4'hF;
      if (t.write && t.strb[0] == 4'h0) t.strb[0] = 4'hF;
      return t;
    endfunction
    virtual function void bus2reg(uvm_sequence_item bus_item, ref uvm_reg_bus_op rw);
      axi4_item t;
      if (!$cast(t, bus_item)) `uvm_fatal("RAL_ADAPT", "not an axi4_item")
      rw.kind   = t.write ? UVM_WRITE : UVM_READ;
      rw.addr   = t.addr;
      rw.data   = t.data.size() ? t.data[0] : 0;
      rw.status = (t.resp.size() && t.resp[0] == AXI4_OKAY) ? UVM_IS_OK : UVM_NOT_OK;
    endfunction
  endclass
endpackage
`endif
